fn prime_num(n: u64) -> bool {
    // By given assumption, n >= 2

    if n == 2 {
        // 2 is prime
        return true;
    }

    // If n is even and greater than 2, it's not prime
    if n % 2 == 0 {
        return false;
    }

    // Calculate integer square root (floor)
    // Use checked casting to avoid float precision edge cases
    let limit = (n as f64).sqrt() as u64;

    // Test odd divisors only, starting from 3 (since even checked above)
    let mut k = 3;
    while k <= limit {
        if n % k == 0 {
            return false;
        }
        k += 2;
    }

    // No divisor found => prime
    true
}